#include "../src/settings.hpp"
#include "../src/replay_buffer.hpp"
#include <iostream>
static void require(bool v,const char* message){if(!v)throw std::runtime_error(message);}
static arc::ReplayPacket packet(uint64_t pts,bool key,size_t size){arc::ReplayPacket p;p.pts=pts;p.key=key;p.size=size;p.memory=std::make_shared<const std::vector<uint8_t>>(size,uint8_t(42));return p;}
int main(){try{
 arc::ReplayBuffer ring(12,60);ring.append(packet(0,false,3));require(!ring.bytes(),"Ignore undecodable leading frame");ring.append(packet(0,true,3));ring.append(packet(1500,false,3));ring.append(packet(3000,false,3));auto saved=ring.snapshot();ring.append(packet(4500,true,3));ring.append(packet(6000,false,3));require(ring.bytes()==6&&ring.snapshot().front().pts==4500,"Evict entire multi-frame GOP");require(saved.size()==3&&saved.front().read()==std::vector<uint8_t>(3,42),"Snapshot survives eviction");ring.configure(2,60);require(ring.bytes()==0,"Byte limit rejects oversize GOP");ring.append(packet(7500,false,1));require(!ring.bytes(),"Remain empty until next key");
 arc::ReplayBuffer timed(1024,2);for(unsigned i=0;i<8;++i)timed.append(packet(uint64_t(i)*90000,i%2==0,1));require(timed.snapshot().front().pts==4*90000&&timed.seconds()==3,"Duration trim keeps preceding keyframe");
 auto file=std::make_shared<arc::ReplayCacheFile>();file->path=std::filesystem::temp_directory_path()/(L"ArcGlass-ReplayTests-"+std::to_wstring(GetCurrentProcessId())+L".agcache");{std::ofstream out(file->path,std::ios::binary);out.write("sample",6);}arc::ReplayPacket cached;cached.file=file;cached.offset=1;cached.size=3;require(cached.read()==std::vector<uint8_t>({'a','m','p'}),"Disk packet offset and read");auto path=file->path;file.reset();require(std::filesystem::exists(path),"Snapshot owns cache file");cached.file.reset();require(!std::filesystem::exists(path),"Cache file released with last owner");
 arc::Settings config;config.monitor.theme=3;config.notificationPosition=5;auto& r=config.replay;r.fps=120;r.bitrate=100;r.width=2560;r.height=1440;r.seconds=1800;r.toggleModifiers=MOD_CONTROL|MOD_ALT;r.toggleKey='R';r.cacheMiB=512;r.diskCache=true;r.windowCapture=true;r.hotModifiers=MOD_CONTROL|MOD_SHIFT;r.hotKey='R';r.saveDirectory=L"D:\\回放 视频";r.cacheDirectory=L"D:\\缓存";r.windowTitle=L"测试游戏";r.windowExe=L"D:\\Games\\Test.exe";std::wstringstream stream;arc::writeSettings(stream,config);arc::Settings restored;require(arc::readSettings(stream,restored)&&restored.replay==r&&restored.monitor.theme==3&&restored.notificationPosition==5,"Replay and independent monitor theme persist");r.seconds=9999;r.width=1;r.height=1;r.fps=0;r.bitrate=0;r.cacheMiB=0;config.sanitize();require(r.seconds==1800&&r.width==320&&r.height==240&&r.fps==15&&r.bitrate==1&&r.cacheMiB==64,"Replay limits sanitized");std::cout<<"Replay GOP limits, snapshot ownership, disk cleanup and settings passed\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
